BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_temp.ct87_preimagen) OR EXISTS(SELECT identidad FROM pg_temp.ct87_preimagen GROUP BY identidad HAVING count(*)<>1) THEN
