   OR EXISTS(SELECT 1 FROM pg_class c,LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.oid=oid_tabla AND a.grantee<>propietario)
   OR has_table_privilege(ejecutor,oid_tabla,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE')
