  RAISE EXCEPTION 'CT87: preparación aislada podría confirmar';END IF;
 FOR f IN SELECT p.* FROM pg_proc p WHERE p.pronamespace='vec_contratacion_temporal'::regnamespace
  AND (p.proname LIKE 'cierre87_%' OR p.proname IN('estado_seguimiento_continuado_canonico_v1','preparar_cierre_administrativo_sin_cese_v1','confirmar_cierre_administrativo_sin_cese_v1','consultar_preparacion_cierre_administrativo_sin_cese_v1')) LOOP
  IF f.proowner<>propietario OR NOT ('search_path=pg_catalog'=ANY(f.proconfig)) THEN RAISE EXCEPTION 'CT87: propietario/search_path inválido';END IF;
  IF f.proname IN('preparar_cierre_administrativo_sin_cese_v1','confirmar_cierre_administrativo_sin_cese_v1','consultar_preparacion_cierre_administrativo_sin_cese_v1') THEN
   IF NOT f.prosecdef OR f.provolatile<>(CASE WHEN f.proname='consultar_preparacion_cierre_administrativo_sin_cese_v1' THEN 's' ELSE 'v' END)::"char" OR NOT has_function_privilege(ejecutor,f.oid,'EXECUTE')
    OR EXISTS(SELECT 1 FROM aclexplode(f.proacl) a WHERE a.grantee NOT IN(propietario,ejecutor) OR a.is_grantable) THEN
    RAISE EXCEPTION 'CT87: frontera pública incorrecta';END IF;
  ELSIF f.prosecdef OR EXISTS(SELECT 1 FROM aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a WHERE a.grantee<>propietario) THEN
